// กติกา: ห้ามปล่อยตำแหน่งว่าง ถ้ามีสมาชิกที่ผ่านเงื่อนไข → ต้องเติม/เลื่อนขึ้นแทนทันที
const s = $json || {};
const sm = s.summary || {};
const mustFill = (sm.vacancies || 0) > 0 && (sm.readyCandidates || 0) > 0;
const slots = (s.vacancies || []).filter(function (v) { return v.kind === 'slot'; }).length;
const positions = (s.vacancies || []).filter(function (v) { return v.kind === 'position'; }).length;
return [{ json: {
  workflow: '1x5 Autopilot 03 · refill check',
  ok: s.ok !== false,
  period: s.period || null,
  vacancies: sm.vacancies || 0,
  slotVacancies: slots,
  positionVacancies: positions,
  readyCandidates: sm.readyCandidates || 0,
  mustFill: mustFill,
  idempotencyKey: 'net1x5-fill-' + new Date().toISOString().slice(0, 13),
  checkedAt: new Date().toISOString()
} }];

// สรุปการจัดสายงาน 1:5 หลังเติมตำแหน่งว่าง
const r = $json || {};
const sm = r.summary || {};
const relink = (r.steps || []).filter(function (s) { return s.key === 'relink' || s.key === 'promote'; }).map(function (s) { return { step: s.key, count: s.count, detail: s.detail }; });
return [{ json: {
  workflow: '1x5 Autopilot 03 · refill applied',
  ok: r.ok !== false,
  runId: r.runId || null,
  promoted: sm.promotedLast || 0,
  vacanciesLeft: sm.vacancies || 0,
  steps: relink,
  warnings: r.warnings || [],
  finishedAt: new Date().toISOString()
} }];
